sys_script_include.script:
var CPMEvidence = Class.create();
CPMEvidence.prototype = {
  // first base64 characters of each allowed file type
  SIGNATURES: {
    'image/png': 'iVBORw0KGgo',
    'image/jpeg': '/9j/',
    'image/gif': 'R0lGOD',
    'image/webp': 'UklGR',
    'application/pdf': 'JVBERi0'
  },

  initialize: function() {
    this.K = new CPMConst();
    this.T = this.K.TABLE;
    this.S = this.K.STATE;
    this.ST = this.K.STATUS;
    this.util = new CPMUtil();
    this.access = new CPMAccess();
    this.msg = new CPMMsg();
  },

  // can the owner send evidence in this state? Missing, rejected, expired, or approval ending soon
  canSubmit: function(state, validUntil) {
    var shown = this.util.effective(state, validUntil);
    return shown == this.S.MISSING || shown == this.S.REJECTED || shown == this.S.EXPIRED || shown == this.K.VIEW.EXPIRING;
  },

  // is a submission already waiting for review?
  hasPending: function(mappingId) {
    var gr = new GlideRecord(this.T.EVIDENCE);
    gr.addQuery('mapping', mappingId);
    gr.addQuery('status', this.ST.PENDING);
    gr.setLimit(1);
    gr.query();
    return gr.hasNext();
  },

  // step 1: adds a file to the owner's private draft ("first" restarts the draft)
  addFile: function(mappingId, file, content, first) {
    var checked = this._checkOwner(mappingId);
    if (checked.error) return this._fail(checked.error.key, checked.error.args);
    var problem = this._validate(file, content);
    if (problem) return this._fail(problem.key, problem.args);

    if (first) {
      var old = this._draftFor(mappingId);
      if (old) old.deleteRecord();
    }
    var draft = this._draftFor(mappingId) || this._createDraft(mappingId);
    if (this._countFiles(draft) >= this.K.MAX_FILES) return this._fail('cpm.err.too_many_files', [this.K.MAX_FILES]);

    var saved = new GlideSysAttachment().writeBase64(draft, file.name, file.type, content);
    if (!saved) return this._fail('cpm.err.file_save');
    return { ok: true, message: this.msg.get('cpm.ok.file_received') };
  },

  // step 2: sends the draft to the compliance team
  submit: function(mappingId) {
    var checked = this._checkOwner(mappingId);
    if (checked.error) return this._fail(checked.error.key, checked.error.args);
    var draft = this._draftFor(mappingId);
    if (!draft || !this._countFiles(draft)) return this._fail('cpm.err.no_files');

    draft.setValue('status', this.ST.PENDING);
    draft.setValue('submitted_on', new GlideDateTime().getValue());
    draft.update();

    new CPMMapping().refreshState(mappingId);
    gs.eventQueue(this.K.EVENT.SUBMITTED, draft, '', '');
    return { ok: true, message: this.msg.get('cpm.ok.submitted') };
  },

  // content of a submitted file (base64). The team opens any file, an owner only their own
  getFile: function(evidenceId, attachmentId) {
    var evidence = new GlideRecord(this.T.EVIDENCE);
    if (!evidenceId || !evidence.get(evidenceId) || evidence.getValue('status') == this.ST.DRAFT)
      return { ok: false, message: this.msg.get('cpm.err.file_unavailable') };
    var mapping = new GlideRecord(this.T.MAPPING);
    if (!mapping.get(evidence.getValue('mapping')) || !this.access.canSee(mapping))
      return { ok: false, message: this.msg.get('cpm.err.file_forbidden') };

    var att = new GlideSysAttachment().getAttachments(this.T.EVIDENCE, evidenceId);
    while (att.next()) {
      if (att.getUniqueValue() != attachmentId) continue;
      return {
        ok: true,
        name: att.getValue('file_name'),
        type: att.getValue('content_type') || 'application/octet-stream',
        content: new GlideSysAttachment().getContentBase64(att)
      };
    }
    return { ok: false, message: this.msg.get('cpm.err.file_not_found') };
  },

  // nightly: deletes drafts older than one day
  cleanupDrafts: function() {
    var gr = new GlideRecord(this.T.EVIDENCE);
    gr.addQuery('status', this.ST.DRAFT);
    gr.addQuery('sys_created_on', '<', gs.daysAgoStart(1));
    gr.query();
    while (gr.next()) gr.deleteRecord();
  },

  // checks that the user may upload for this mapping
  _checkOwner: function(mappingId) {
    var mapping = new GlideRecord(this.T.MAPPING);
    if (!mappingId || !mapping.get(mappingId)) return { error: { key: 'cpm.err.control_not_found' } };
    if (!this.access.isOwnerOf(mapping)) return { error: { key: 'cpm.err.owner_only' } };
    if (!this.util.on(mapping.getValue('active')) || !this.canSubmit(mapping.getValue('state'), mapping.getValue('valid_until')))
      return { error: { key: 'cpm.err.not_accepting' } };
    if (this.hasPending(mappingId)) return { error: { key: 'cpm.err.pending_exists' } };
    return { mapping: mapping };
  },

  // server-side check of name, type, content and size
  _validate: function(file, content) {
    var maxMb = this.util.intProp('max_file_mb', 3);
    if (!file.name) return { key: 'cpm.err.file_name_missing' };
    if (!this.SIGNATURES[file.type]) return { key: 'cpm.err.file_type' };
    if (!/\.(png|jpe?g|gif|webp|pdf)$/i.test(file.name)) return { key: 'cpm.err.file_ext' };
    if (!content) return { key: 'cpm.err.file_empty' };
    if (content.indexOf(this.SIGNATURES[file.type]) !== 0) return { key: 'cpm.err.file_mismatch' };
    if (Math.floor(content.length * 3 / 4) > maxMb * 1024 * 1024) return { key: 'cpm.err.file_size', args: [maxMb] };
    return null;
  },

  _draftFor: function(mappingId) {
    var gr = new GlideRecord(this.T.EVIDENCE);
    gr.addQuery('mapping', mappingId);
    gr.addQuery('status', this.ST.DRAFT);
    gr.addQuery('submitted_by', gs.getUserID());
    gr.setLimit(1);
    gr.query();
    return gr.next() ? gr : null;
  },

  _createDraft: function(mappingId) {
    var gr = new GlideRecord(this.T.EVIDENCE);
    gr.initialize();
    gr.setValue('mapping', mappingId);
    gr.setValue('status', this.ST.DRAFT);
    gr.setValue('submitted_by', gs.getUserID());
    gr.insert();
    return gr;
  },

  _countFiles: function(evidence) {
    var n = 0;
    var att = new GlideSysAttachment().getAttachments(this.T.EVIDENCE, evidence.getUniqueValue());
    while (att.next()) n++;
    return n;
  },

  _fail: function(key, args) {
    return { ok: false, message: this.msg.get(key, args) };
  },

  type: 'CPMEvidence'
};
